<script lang="ts">
  import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { contains } from '../shared/dom.js'; import { composeEventHandlers } from '../shared/events.js'; import { getPopoverContext } from '../popover/popover-context.svelte.js'; import { getSelectContext } from './select-context.svelte.js';
  export interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> { children?: Snippet; ref?: HTMLDivElement | null; }
  let { children, ref = $bindable(null), onkeydown, ...rest }: Props = $props(); const select = getSelectContext(); const popover = getPopoverContext();
  function attach(node: HTMLDivElement) { popover.popup = node; queueMicrotask(() => { const selected = select.selectedItem ?? select.items.find((item) => !item.disabled); select.highlighted = selected?.value ?? null; selected?.element?.focus(); }); const outside = (event: PointerEvent) => { if (!contains(node, event.target) && !contains(popover.trigger, event.target)) popover.setOpen(false, 'outside-press', event); }; document.addEventListener('pointerdown', outside, true); return () => document.removeEventListener('pointerdown', outside, true); }
  function keydown(event: KeyboardEvent) { if (event.key === 'ArrowDown') { event.preventDefault(); select.moveHighlight(1); } if (event.key === 'ArrowUp') { event.preventDefault(); select.moveHighlight(-1); } if (event.key === 'Home') { event.preventDefault(); const first = select.items.find((item) => !item.disabled); select.highlighted = first?.value ?? null; first?.element?.focus(); } if (event.key === 'End') { event.preventDefault(); const last = select.items.filter((item) => !item.disabled).at(-1); select.highlighted = last?.value ?? null; last?.element?.focus(); } if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); if (select.highlighted) select.select(select.highlighted, event); } if (event.key === 'Escape') { event.preventDefault(); popover.setOpen(false, 'escape-key', event); popover.trigger?.focus(); } }
</script>
{#if popover.open}<div bind:this={ref} {...rest} tabindex="-1" data-open="" data-side={popover.side} data-align={popover.align} onkeydown={composeEventHandlers(onkeydown, keydown)} {@attach attach}>{@render children?.()}</div>{/if}
